"""Separate visual regression: recovered client-only CSS/timers, never simulation events."""
import argparse,json,unittest
from pathlib import Path
from test_umbra_browser import UmbraBrowser
from test_continuity import RecordedResult
class EasterVisuals(UmbraBrowser):
 def enable(self,p):
  self.tab(p,'settings');p.locator('#umbra-anomalies').check();p.locator('#infestationLevel').select_option('outbreak');p.locator('#glitchEffects').check();self.tab(p,'home')
 def test_egg_original_acid_growth_radar_and_persistence(self):
  p=self.page();self.enable(p);self.assertEqual(p.locator('.umbra-acid').evaluate('(e)=>getComputedStyle(e).display'),'block');self.assertEqual(p.locator('.wy-bio-stain').evaluate('(e)=>getComputedStyle(e).display'),'block');p.wait_for_timeout(1300);self.assertAlmostEqual(float(p.locator('.wy-bio-stain').evaluate('(e)=>getComputedStyle(e).opacity')),.65,places=1);self.assertEqual(p.locator('.wy-radar').evaluate('(e)=>getComputedStyle(e,"::after").animationName'),'wy-sweep');p.locator('.umbra-acid').evaluate('(e)=>{const a=e.getAnimations().find(a=>a.animationName==="umbra-drip");a.pause();a.currentTime=6220;}');self.assertGreater(float(p.locator('.umbra-acid').evaluate('(e)=>getComputedStyle(e).opacity')),.5);p.reload();p.wait_for_function('!!window.UmbraApp');self.assertEqual(p.evaluate('document.body.dataset.infestation'),'outbreak');self.assertEqual(p.locator('.wy-bio-stain').evaluate('(e)=>getComputedStyle(e).display'),'block');self.tab(p,'icarus');self.assertEqual(p.locator('.umbra-acid').evaluate('(e)=>getComputedStyle(e).display'),'none')
 def test_egg_master_and_reduced_motion_preserve_safety(self):
  p=self.page();self.assertEqual(p.evaluate('document.body.dataset.infestation'),'off');self.enable(p);p.emulate_media(reduced_motion='reduce');self.assertEqual(p.locator('.umbra-acid').evaluate('(e)=>getComputedStyle(e).animationName'),'none');self.assertEqual(p.locator('.wy-radar').evaluate('(e)=>getComputedStyle(e,"::after").animationName'),'none');self.tab(p,'settings');p.locator('#umbra-anomalies').uncheck();self.tab(p,'home');self.assertEqual(p.locator('.umbra-acid').evaluate('(e)=>getComputedStyle(e).display'),'none');self.assertEqual(p.evaluate('document.body.classList.contains("wy-glitch-now")'),False)
 def test_egg_recovered_timers_are_client_only_and_asset_archive_still_works(self):
  p=self.page(clock=True);self.enable(p);p.locator('nav button[data-tab=home]').blur();p.evaluate("""() => { window.eggObservations={readout:0,glitch:0};window.originalRandom=Math.random;Math.random=()=>0;new MutationObserver(()=>{if(document.getElementById('bioReadout').textContent.includes('FICTIONAL MOTIF'))eggObservations.readout++;}).observe(document.getElementById('bioReadout'),{childList:true});new MutationObserver(()=>{if(document.body.classList.contains('wy-glitch-now'))eggObservations.glitch++;}).observe(document.body,{attributes:true,attributeFilter:['class']}); }""");p.clock.fast_forward(300001);p.clock.fast_forward(24000);counts=p.evaluate('eggObservations');self.assertGreater(counts['readout'],0);self.assertGreater(counts['glitch'],0);self.assertEqual(p.evaluate('typeof __icarusSoak'),'undefined');p.evaluate('() => { Math.random=originalRandom; }');self.tab(p,'settings');p.wait_for_function('UmbraApp.archiveReady');p.locator('#umbra-arcade-archive summary').click();p.locator('#umbra-arcade-gallery button').first.click();self.assertIn('FICTIONAL',p.locator('#umbra-arcade-caption').inner_text());p.wait_for_function('document.querySelector("#umbra-arcade-preview").complete&&document.querySelector("#umbra-arcade-preview").naturalWidth===128');self.assertTrue(p.locator('#umbra-arcade-preview').is_visible())
if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--runtime',type=Path);ap.add_argument('--report',type=Path,required=True);a=ap.parse_args()
 if a.runtime:
  import test_umbra_browser;test_umbra_browser.ROOT=a.runtime.resolve()
 names=[n for n in unittest.defaultTestLoader.getTestCaseNames(EasterVisuals) if n.startswith('test_egg_')];r=unittest.TextTestRunner(verbosity=2,resultclass=RecordedResult).run(unittest.TestSuite(EasterVisuals(n) for n in names));a.report.parent.mkdir(parents=True,exist_ok=True);a.report.write_text(json.dumps({'passed':r.wasSuccessful(),'tests_run':r.testsRun,'passed_cases':r.successes,'failures':[{'test':str(t),'detail':d} for t,d in r.failures],'errors':[{'test':str(t),'detail':d} for t,d in r.errors]},indent=2));raise SystemExit(not r.wasSuccessful())
